/* From Uiverse.io by Shoh2008 - Tags: button */
.__UIV_SCOPE__ button {
  font: 18px;
  color: #fff;
  text-decoration: none;
  text-transform: uppercase;
  padding: 5px 20px;
  position: relative;
  overflow: hidden;
  border-radius: 5px;
  transition: 0.2s;
  transform: scale(2);
  border: 1px solid;
}

.__UIV_SCOPE__ button span {
  position: relative;
  z-index: 0;
  display: flex;
  color: #fff;
}

.__UIV_SCOPE__ button .liquid {
  position: absolute;
  top: -50px;
  left: 0;
  width: 100%;
  height: 150px;
  background: #FF229F;
  box-shadow: inset 0 0 50px rgba(0, 0, 0, 0.7);
  z-index: -1;
  transition: 0.6s;
}

.__UIV_SCOPE__ button .liquid::after,
.__UIV_SCOPE__ button .liquid::before {
  position: absolute;
  content: "🪐";
  width: 200%;
  height: 200%;
  top: 0;
  left: 0;
  transform: translate(-25%, -75%);
}

.__UIV_SCOPE__ button .liquid::after {
  border-radius: 45%;
  background: rgba(20, 20, 20, 1);
  box-shadow: 0 0 10px 5px #33053C, inset 0 0 5px #33053C;
  animation: animate 5s linear infinite;
  opacity: 0.8;
}

.__UIV_SCOPE__ button .liquid::before {
  content: "🚀";
  border-radius: 40%;
  box-shadow: 0 0 10px rgba(26, 26, 26, 0.5),
        inset 0 0 5px rgba(26, 26, 26, 0.5);
  background: rgba(26, 26, 26, 0.5);
  animation: animate_3881 7s linear infinite;
}

@keyframes animate_3881 {
  0% {
    transform: translate(-25%, -75%) rotate(0);
  }

  100% {
    transform: translate(-25%, -75%) rotate(360deg);
  }
}

.__UIV_SCOPE__ button:hover .liquid {
  top: -120px;
}

.__UIV_SCOPE__ button:hover {
  box-shadow: 0 0 5px #33053C, inset 0 0 5px #33053C;
  transition-delay: 0.2s;
}
